import React from 'react'
import { connect } from 'react-redux'
import { Checkbox, Button, Row, Col, Input, Form, Radio, Spin } from 'antd'
import { injectIntl } from 'react-intl'
import IntlMessages from '../../components/utility/intlMessages'
import PropTypes from 'prop-types'
import FeedbackModalStyle from './feedbackModal.style'
import claimActions from '../../redux/claim/actions'
import renderEmoticons from './renderEmoticon'
import thankyou from '../../image/thank-you.png'

const { TextArea } = Input
const FormItem = Form.Item

const {
  getFeedbackForms,
  resetReduxState,
  postFeedbackForms
} = claimActions

class FeedbackModal extends React.Component {
  state = {
    loading: false,
    rating: undefined,
    thankYou: false,
    activeIndex: [],
    alreadySubmitted: false,
    postingFeedback: false
  }

  componentDidMount () {
    const { match } = this.props
    if (match.params.id) {
      this.setState({ feedback_request_id: match.params.id })
      if (match.params.rating) {
        this.setState({
          rating: parseInt(match.params.rating, 10)
        })
      }
    }
    this.props.getFeedbackForms({ reqId: match.params.id, rating: match.params.rating })
    this.props.resetReduxState(['feedbackForms', 'getFeedbackFormStatus', 'postFeedbackFormStatus'])
  }

  componentWillReceiveProps (nextProps) {
    const { match } = this.props
    const { thankYou } = this.state
    const {
      getFeedbackFormStatus,
      postFeedbackFormStatus
    } = nextProps
    if (getFeedbackFormStatus === '') {
      this.props.getFeedbackForms({ reqId: match.params.id, rating: match.params.rating })
    }
    if (postFeedbackFormStatus === 'Success' && !thankYou) {
      this.setState({
        thankYou: true,
        postingFeedback: false
      })
    }
    if (getFeedbackFormStatus === 'Feedback form already submitted') {
      this.setState({ alreadySubmitted: true })
    }
  }

  handleCancel = () => {
    this.props.resetReduxState(['feedbackForms', 'getFeedbackFormStatus', 'postFeedbackFormStatus'])
    this.props.history.push('/')
  }

  handleOk = () => {
    this.setState({ loading: true })
    setTimeout(() => {
      this.props.onOk()
    }, 2000)
  }

  intlText = (messageObj = { id: ' ' }) => {
    return this.props.intl.formatMessage(messageObj)
  }

  onRatingChange = e => {
    this.props.getFeedbackForms({ reqId: this.state.feedback_request_id, rating: e.target.value })
    this.props.form.resetFields()
    this.setState({
      rating: e.target.value, activeIndex: []
    })
  }

  async validateForm () {
    return new Promise((resolve) => {
      this.props.form.validateFields((error, values) => {
        resolve(!error)
      })
    })
  }

  onSubmit = async e => {
    e.preventDefault()
    const valid = await this.validateForm()
    if (!valid) {
      return
    }
    const {
      form
    } = this.props
    const formValues = form.getFieldsValue()
    let source = window.sessionStorage.getItem('utm_source')
    if (!source) {
      source = 'direct'
    }
    let payload = {
      ...formValues,
      feedback_request_id: this.state.feedback_request_id,
      source: source
    }
    this.setState({ postingFeedback: true })
    this.props.postFeedbackForms(payload)
  }

  changeCheckbox = (value) => {
    let activeIndex = this.state.activeIndex
    let as = activeIndex.indexOf(value)
    if (as === -1) {
      activeIndex.push(value)
    } else {
      activeIndex = activeIndex.filter((val, index, arr) => { return val !== value })
    }
    this.setState({ activeIndex: activeIndex })
  }

  render () {
    const {
      thankYou,
      alreadySubmitted,
      activeIndex
    } = this.state
    const {
      form,
      feedbackFormLoader,
      feedbackForms
    } = this.props
    const { getFieldDecorator } = form
    let questionText = this.intlText({ id: 'Saya ingin layanan ditingkatkan?' })
    let commentText = this.intlText({ id: 'Apa yang bisa kita tingkatkan?' })
    let options = []
    let requiredLabel = true
    let requiredTitle = true

    if (Object.keys(feedbackForms).length > 0) {
      questionText = this.intlText({ id: feedbackForms.label })
      options = feedbackForms.options
      commentText = this.intlText({ id: feedbackForms.title })
      requiredLabel = feedbackForms.is_required_label
      requiredTitle = feedbackForms.is_required_title
    }

    return (
      <FeedbackModalStyle>
        {alreadySubmitted ? (
          <div style={{ marginTop: '50px', marginBottom: '30px' }}>
            <Row type='flex' justify='center'>
              <Col lg={18}>
                <center>
                  <img src={thankyou} style={{ width: '214px', height: '155px', marginTop: '35px', marginBottom: '20px' }} alt='' />
                  <div style={{ marginBottom: '45px', fontFamily: 'Muli', fontSize: '15px', padding: '20px' }}>
                    <span>
                      <IntlMessages id='Ulasan Anda sudah dikirimkan untuk klaim ini. ' />
                    </span>
                  </div>
                  <Button
                    className='succes-page-button'
                    onClick={this.handleCancel}
                  >
                    <IntlMessages id='baik' />
                  </Button>
                </center>
              </Col>
            </Row>
          </div>
        )
          : (
            !thankYou ? ([
              <Spin spinning={Object.keys(feedbackForms).length === 0 || this.state.postingFeedback || feedbackFormLoader}>
                <Row type='flex' justify='center'>
                  <Col lg={18}>
                    <div className='feedback-header'>
                      <IntlMessages id='Umpan Balik' />
                    </div>
                    <Form id='event-form' onSubmit={this.onSubmit} style={{ marginTop: '10px' }}>
                      <Row>
                        <Col xs={24}>
                          <div className='first claim-validation-content'>
                            <center><Form.Item label={this.intlText({ id: 'Pilih Peringkat Anda' })}>
                              {getFieldDecorator('rating', {
                                rules: [
                                  { required: true, message: 'Rating cannot be empty' }
                                ],
                                initialValue: this.state.rating
                              })(
                                <Radio.Group onChange={this.onRatingChange} defaultValue={this.state.rating}>
                                  <Radio.Button value={1}>
                                    {this.state.rating === 1 ? renderEmoticons('1') : renderEmoticons('1d')}
                                    <p className='smiley-text'><IntlMessages id='Sangat tidak puas' /></p>
                                  </Radio.Button>
                                  <Radio.Button value={2}>
                                    {this.state.rating === 2 ? renderEmoticons('2') : renderEmoticons('2d')}
                                    <p className='smiley-text'><IntlMessages id='kurang puas' /></p>
                                  </Radio.Button>
                                  <Radio.Button value={3}>
                                    {this.state.rating === 3 ? renderEmoticons('3') : renderEmoticons('3d')}
                                    <p className='smiley-text'><IntlMessages id='cukup' /></p>
                                  </Radio.Button>
                                  <Radio.Button value={4}>
                                    {this.state.rating === 4 ? renderEmoticons('4') : renderEmoticons('4d')}
                                    <p className='smiley-text'><IntlMessages id='puas' /></p>
                                  </Radio.Button>
                                  <Radio.Button value={5}>
                                    {this.state.rating === 5 ? renderEmoticons('5') : renderEmoticons('5d')}
                                    <p className='smiley-text'><IntlMessages id='sangat puas' /></p>
                                  </Radio.Button>
                                </Radio.Group>
                              )}
                            </Form.Item>
                            </center>
                          </div>
                        </Col>
                      </Row>
                      <Row>
                        <Col xs={24} lg={12}>
                          <div className='claim-validation-content '>
                            <Form.Item label={questionText}>
                              {getFieldDecorator('submitted_options', {
                                rules: [
                                  { required: requiredLabel, message: 'Opsi tidak boleh kosong' }
                                ]
                              })(
                                <Checkbox.Group >
                                  {
                                    options.map((value, index) => {
                                      return (
                                        <Checkbox className={(activeIndex.indexOf(value.name) > -1) ? 'active-class checkbox-wrapper' : 'inactive-class checkbox-wrapper'}
                                          key={index} value={value.name} onClick={() => this.changeCheckbox(value.name)}>{this.intlText({ id: value.label })}</Checkbox>
                                      )
                                    })
                                  }
                                </Checkbox.Group>
                              )}
                            </Form.Item>
                          </div>
                        </Col>
                        <Col xs={24} lg={12}>
                          <div className='claim-validation-content'>
                            <FormItem label={commentText}>
                              {
                                getFieldDecorator('review', {
                                  rules: [
                                    { required: requiredTitle, message: 'Ulasan tidak boleh kosong' }
                                  ]
                                })(
                                  <TextArea rows={4} />
                                )
                              }
                            </FormItem>
                          </div>
                        </Col>
                      </Row>
                      <Row>
                        <Col xs={24} >
                          <div className='submit-feedback-btn'>
                            <center>
                              <FormItem>
                                <Button
                                  form='event-form'
                                  className='yes-btn-claim-validation'
                                  key='submit'
                                  type='primary'
                                  htmlType='submit'
                                // loading={postProviderUserLoading}
                                >
                                  {this.intlText({ id: 'Simpan' })}
                                </Button>
                              </FormItem>
                            </center>
                          </div>
                        </Col>
                      </Row>
                    </Form>
                  </Col>
                </Row>
              </Spin>
            ]) : (
              <div style={{ marginTop: '50px', marginBottom: '30px' }}>
                <Row type='flex' justify='center'>
                  <Col lg={18}>
                    <center>
                      <img src={thankyou} style={{ width: '214px', height: '155px', marginTop: '35px', marginBottom: '20px' }} alt='' />
                      <div style={{ marginBottom: '45px', fontFamily: 'Muli', fontSize: '15px' }}>
                        <IntlMessages id='Terima kasih atas penilaian Anda. Selalu gunakan Pasarpolis untuk lindungi setiap kebutuhan Anda' />
                      </div>
                      <Button
                        className='succes-page-button'
                        onClick={this.handleCancel}
                      >
                        <IntlMessages id='baik' />
                      </Button>
                    </center>
                  </Col>
                </Row>
              </div>
            )
          )
        }
      </FeedbackModalStyle>
    )
  }
}

const WrappedFeedbackModal = Form.create()(injectIntl(FeedbackModal))

WrappedFeedbackModal.propTypes = {
  event: PropTypes.string,
  userid: PropTypes.string,
  userName: PropTypes.string
}

WrappedFeedbackModal.defaultProps = {
  event: '',
  userid: '',
  userName: ''
}

export default connect(
  state => ({
    feedbackForms: state.Claim.feedbackForms,
    feedbackFormLoader: state.Loading.GET_FEEDBACK_FORMS,
    getFeedbackFormStatus: state.Claim.getFeedbackFormStatus,
    postFeedbackFormStatus: state.Claim.postFeedbackFormStatus
  }),
  {
    getFeedbackForms,
    resetReduxState,
    postFeedbackForms
  }
)(WrappedFeedbackModal)
