import sm1 from '../../image/smiley1.png'
import sm2 from '../../image/smiley2.png'
import sm3 from '../../image/smiley3.png'
import sm4 from '../../image/smiley4.png'
import sm5 from '../../image/smiley5.png'
import sm1d from '../../image/smiley1_d.png'
import sm2d from '../../image/smiley2_d.png'
import sm3d from '../../image/smiley3_d.png'
import sm4d from '../../image/smiley4_d.png'
import sm5d from '../../image/smiley5_d.png'

const renderEmoticons = rating => {
  const dict = {
    '1': (
      <img alt='feedback' src={sm1} className='feedback-smiley' />
    ),
    '2': (
      <img alt='feedback' src={sm2} className='feedback-smiley' />
    ),
    '3': (
      <img alt='feedback' src={sm3} className='feedback-smiley' />
    ),
    '4': (
      <img alt='feedback' src={sm4} className='feedback-smiley' />
    ),
    '5': (
      <img alt='feedback' src={sm5} className='feedback-smiley' />
    ),
    '1d': (
      <img alt='feedback' src={sm1d} className='feedback-smiley' />
    ),
    '2d': (
      <img alt='feedback' src={sm2d} className='feedback-smiley' />
    ),
    '3d': (
      <img alt='feedback' src={sm3d} className='feedback-smiley' />
    ),
    '4d': (
      <img alt='feedback' src={sm4d} className='feedback-smiley' />
    ),
    '5d': (
      <img alt='feedback' src={sm5d} className='feedback-smiley' />
    )
  }
  if (dict.hasOwnProperty(rating)) {
    return dict[rating]
  } else {
    return (
      <img alt='feedback' src={sm1} className='feedback-smiley' />
    )
  }
}

export default renderEmoticons
